begin;
set local search_path=public,private,extensions;
select plan(28);
grant usage on schema extensions to authenticated;
update private.admin_execution_environment_v1 set environment='DEVELOPMENT',configuration_reference='ROLLBACK-ONLY-PROVIDER-IDENTITY-0350'where singleton;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select('a3500000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','identity0350-'||i||'@example.invalid',now(),'{}','{}',now(),now()from generate_series(1,5)i;
insert into public.organizations(id,legal_name,display_name,status,created_by)values('a3501000-0000-4000-8000-000000000001','TEST identité Provider','TEST identité Provider','PENDING','a3500000-0000-4000-8000-000000000001'),('a3501000-0000-4000-8000-000000000002','TEST autre organisation','TEST autre organisation','PENDING','a3500000-0000-4000-8000-000000000003');
insert into public.organization_identifiers(organization_id,identifier_type,normalized_value)values('a3501000-0000-4000-8000-000000000001','ICE','993500000000001'),('a3501000-0000-4000-8000-000000000002','ICE','993500000000002');
insert into public.organization_memberships(id,organization_id,user_id,status)select('a3502000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'a3501000-0000-4000-8000-000000000001',('a3500000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'ACTIVE'from generate_series(1,3)i;
insert into public.organization_member_roles(membership_id,role_code)values('a3502000-0000-4000-8000-000000000001','PROVIDER_OWNER'),('a3502000-0000-4000-8000-000000000002','PROVIDER_MANAGER'),('a3502000-0000-4000-8000-000000000003','PROVIDER_VIEWER');
insert into public.platform_user_roles(user_id,role_code)values('a3500000-0000-4000-8000-000000000004','COMPLIANCE_MANAGER'),('a3500000-0000-4000-8000-000000000001','COMPLIANCE_MANAGER');
create function pg_temp.actor(n integer,assurance text default 'aal2')returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',('a3500000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'role','authenticated','aal',assurance)::text,true)::void$$;
create function pg_temp.profile()returns jsonb language sql as $$select '{"legal_form":"SARL","incorporation_date":"2020-01-01","activity":"Maintenance technique indépendante","sector":"Services techniques","employee_count":4,"registered_city":"Casablanca","registered_address":{"line1":"Adresse de TEST déclarée","country_code":"MA"},"contact":{"phone":"0600000000","email":"contact0350@example.invalid"},"representative":{"first_name":"TEST","last_name":"Représentant","title":"Gérant","email":"representant0350@example.invalid","phone":"0600000001","power":"Mandat de TEST déclaré"},"declarations":{"accuracy_confirmed":true,"representation_authorized":true},"if_number":"350123456","rc_number":"350123"}'::jsonb$$;
do $$begin execute format('grant usage on schema %I to authenticated',pg_my_temp_schema()::regnamespace);end$$;
select pg_temp.actor(1);
set local role authenticated;
select throws_ok($$select public.save_client_profile_draft('a3501000-0000-4000-8000-000000000001',pg_temp.profile(),'client-denied-0350')$$,'42501','FORBIDDEN','Provider cannot enter Client command');
select throws_ok($$select public.save_provider_legal_profile_v1('a3501000-0000-4000-8000-000000000001',pg_temp.profile()-'representative',0,'missing-rep-0350')$$,'22023','CLIENT_PROFILE_REQUIRED_FIELDS_MISSING','Shared validator requires representative');
select is((public.save_provider_legal_profile_v1('a3501000-0000-4000-8000-000000000001',pg_temp.profile(),0,'provider-save-0350')->>'profile_version')::integer,1,'Provider Owner creates the canonical profile');
select is((public.save_provider_legal_profile_v1('a3501000-0000-4000-8000-000000000001',pg_temp.profile(),0,'provider-save-0350')->>'profile_version')::integer,1,'Exact replay returns the same version');
reset role;
select is((select count(*)::integer from public.client_trials where organization_id='a3501000-0000-4000-8000-000000000001'),0,'No Client trial is created');
select is((select count(*)::integer from public.organization_member_roles mr join public.organization_memberships m on m.id=mr.membership_id where m.organization_id='a3501000-0000-4000-8000-000000000001'and mr.role_code like 'CLIENT_%'),0,'No Client role is activated');
set local role authenticated;
select is((public.get_my_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000001')#>>'{profile,representative,last_name}'),'Représentant','Authorized workspace returns the real saved representative');
select throws_ok($$select public.get_my_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000002')$$,'42501','PROVIDER_IDENTITY_SCOPE_DENIED','Foreign organization denied');
select pg_temp.actor(3);
select throws_ok($$select public.get_my_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000001')$$,'42501','PROVIDER_IDENTITY_SCOPE_DENIED','Viewer cannot read representative data');
select pg_temp.actor(2);
select is((public.get_my_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000001')->>'profile_version')::integer,1,'Provider Manager can read shared profile');
select throws_ok($$select public.save_provider_legal_profile_v1('a3501000-0000-4000-8000-000000000001',pg_temp.profile(),0,'stale-save-0350')$$,'40001','STALE_PROVIDER_LEGAL_PROFILE','Stale draft cannot overwrite a newer version');
select throws_ok($$select public.submit_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000001',1,'a3503000-0000-4000-8000-000000000001')$$,'55000','PROVIDER_PROFILE_REQUIRED','Submission requires Provider qualification profile');
select public.submit_provider_profile('a3501000-0000-4000-8000-000000000001','{"activity_summary":"Activité de TEST pour l’identité commune","team_size":4,"years_experience":3,"secondary_subcontracting_allowed":false,"accounting_contact_email":"accounting0350@example.invalid"}',0,'qualification-profile0350');
select throws_ok($$select public.submit_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000001',1,'a3503000-0000-4000-8000-000000000001')$$,'55000','PROVIDER_LEGAL_DOCUMENTS_REQUIRED','Submission requires all three Provider documents');
reset role;
-- TEST-only storage/scanner port; all record/review commands remain native.
do $$declare u jsonb;d jsonb;job uuid;kind text;begin
 foreach kind in array array['LEGAL','FISCAL','INSURANCE']loop
  perform pg_temp.actor(1);u:=public.begin_provider_document_upload('a3501000-0000-4000-8000-000000000001','application/pdf',20);
  insert into storage.objects(bucket_id,name,owner_id,metadata)values('provider-qualification',u->>'storage_object_path','a3500000-0000-4000-8000-000000000001','{"mimetype":"application/pdf","size":20}');
  d:=public.record_provider_document_version('a3501000-0000-4000-8000-000000000001',kind,'IDENTITY0350_'||kind,jsonb_build_object('issued_on',current_date::text,'expires_on',(current_date+365)::text,'storage_object_path',u->>'storage_object_path','content_hash',repeat('d',64),'metadata',jsonb_build_object('declared_mime_type','application/pdf','declared_size_bytes',20)),array[]::uuid[],'TEST document for independent identity review','identity0350-doc-'||kind);
  select id into job from public.provider_document_scan_jobs where document_version_id=(d->>'document_version_id')::uuid;
  perform set_config('request.jwt.claims','{"role":"service_role"}',true);perform public.record_provider_document_scan_result(job,'CLEAN','SQL_TEST_SCANNER','test-only',repeat('d',64),'identity0350-scan-'||kind);
 end loop;
end$$;
select pg_temp.actor(1);
set local role authenticated;
select is(public.submit_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000001',1,'a3503000-0000-4000-8000-000000000001')->>'outcome','PROVIDER_LEGAL_IDENTITY_SUBMITTED','Exact canonical version and documents submitted');
select is(public.submit_provider_legal_identity_v1('a3501000-0000-4000-8000-000000000001',1,'a3503000-0000-4000-8000-000000000001')->>'outcome','PROVIDER_LEGAL_IDENTITY_SUBMITTED','Submission is idempotent');
select is((select count(*)::integer from public.provider_legal_identity_submissions_v1 where organization_id='a3501000-0000-4000-8000-000000000001'),1,'One immutable submission');
select pg_temp.actor(4);
do $$declare d record;begin for d in select v.id from public.provider_document_versions v where v.provider_organization_id='a3501000-0000-4000-8000-000000000001'and v.status='SUBMITTED'loop perform public.review_provider_document(d.id,'VERIFIED','TEST independent evidence review','TEST-0350','identity0350-review-'||d.id);end loop;end$$;
select public.decide_provider_company('a3501000-0000-4000-8000-000000000001','VERIFIED','NOT_SIGNED',null,'TEST independent company review','TEST-0350',(select row_version from public.provider_profiles where provider_organization_id='a3501000-0000-4000-8000-000000000001'),'identity0350-company');
reset role;
create function pg_temp.review_identity()returns jsonb language plpgsql as $$declare c jsonb;begin c:=public.get_provider_identity_review_context_v1('a3501000-0000-4000-8000-000000000001');return public.revalidate_provider_identity_v1('a3501000-0000-4000-8000-000000000001',(c->>'organization_row_version')::integer,(c->>'profile_row_version')::integer,c->>'identity_hash',(c->>'company_decision_id')::uuid,'TEST exact independent identity review',extensions.gen_random_uuid());end$$;
select pg_temp.actor(1);
set local role authenticated;
select throws_ok($$select pg_temp.review_identity()$$,'42501','PROVIDER_INDEPENDENT_CURRENT_PROFILE_SUBMISSION_REQUIRED','A platform reviewer who authored/submitted this profile cannot approve it');
select pg_temp.actor(4,'aal1');
select throws_ok($$select pg_temp.review_identity()$$,'42501','PROVIDER_IDENTITY_REVIEW_DENIED','Admin AAL1 cannot approve');
select pg_temp.actor(4);
select is(pg_temp.review_identity()->>'outcome','PROVIDER_IDENTITY_VERIFIED','Existing AAL2 independent identity command verifies exact profile');
reset role;
select is((select status from public.organizations where id='a3501000-0000-4000-8000-000000000001'),'ACTIVE','Provider-only organization can become active');
select is((select count(*)::integer from public.client_trials where organization_id='a3501000-0000-4000-8000-000000000001'),0,'Provider activation creates no Client trial');
select ok(private.provider_current_identity_is_verified_v1('a3501000-0000-4000-8000-000000000001'),'Current shared identity is verified');
select pg_temp.actor(2);
set local role authenticated;
select is((public.save_provider_legal_profile_v1('a3501000-0000-4000-8000-000000000001',pg_temp.profile()||'{"registered_address":{"line1":"Nouvelle adresse de TEST","country_code":"MA"}}',1,'provider-revision0350')->>'profile_version')::integer,2,'Manager creates canonical address revision');
reset role;
select ok(not private.provider_current_identity_is_verified_v1('a3501000-0000-4000-8000-000000000001'),'Old attestation cannot approve a new address');
select pg_temp.actor(4);
set local role authenticated;
select throws_ok($$select pg_temp.review_identity()$$,'42501','PROVIDER_INDEPENDENT_CURRENT_PROFILE_SUBMISSION_REQUIRED','Unsubmitted current revision cannot be approved');
select is((select count(*)::integer from public.provider_identity_verification_history where organization_id='a3501000-0000-4000-8000-000000000001'),1,'No second verification is fabricated');
reset role;
select ok(not has_function_privilege('authenticated','private.save_organization_profile_draft_v1(uuid,jsonb,text,uuid)','EXECUTE'),'Runtime cannot bypass domain wrappers');
select ok(not has_function_privilege('service_role','public.save_provider_legal_profile_v1(uuid,jsonb,integer,text,uuid)','EXECUTE'),'Service role cannot impersonate Provider');
select * from finish();
rollback;
